package main

import (
	"fmt"
	"regexp"
)

func main() {
	re := regexp.MustCompile(`\d+`)
	fmt.Println(re.FindString("abc123def45"))     // 123
	fmt.Println(re.FindAllString("a1 b22 c333", -1)) // [1 22 333]
}

package main

import (
	"fmt"
	"regexp"
)

func main() {
	re := regexp.MustCompile(`(\w+)@(\w+)`)
	m := re.FindStringSubmatch("bob@acme")
	if m != nil {
		fmt.Println(m[1], m[2]) // bob acme
	}
}

package main

import (
	"fmt"
	"regexp"
)

var re = regexp.MustCompile(`(?P<user>\w+)@(?P<host>\w+)`)

func main() {
	m := re.FindStringSubmatch("ann@corp")
	names := re.SubexpNames() // ["" "user" "host"]
	for i, v := range m {
		if names[i] != "" {
			fmt.Printf("%s=%s\n", names[i], v)
		}
	}
}

package main

import (
	"fmt"
	"regexp"
)

func main() {
	ws := regexp.MustCompile(`\s+`)
	fmt.Println(ws.ReplaceAllString("a  b   c", " ")) // a b c
	swap := regexp.MustCompile(`(\w+)@(\w+)`)
	fmt.Println(swap.ReplaceAllString("bob@acme", "$2/$1")) // acme/bob
}

