package solution

import (
	"regexp"
	"strconv"
)

// compiled once; -? allows an optional leading minus sign
var intPattern = regexp.MustCompile(`-?\d+`)

func ExtractInts(s string) []int {
	matches := intPattern.FindAllString(s, -1)
	out := make([]int, 0, len(matches)) // non-nil, right-sized
	for _, m := range matches {
		n, err := strconv.Atoi(m)
		if err == nil { // matches are digit runs, so this should not fail
			out = append(out, n)
		}
	}
	return out
}

codeLab.testHarness:
package solution

import (
	"reflect"
	"testing"
)

func TestExtractInts(t *testing.T) {
	cases := []struct {
		in   string
		want []int
	}{
		{"a-5 b12 c", []int{-5, 12}},
		{"no numbers", []int{}},
		{"1 2 3", []int{1, 2, 3}},
	}
	for _, c := range cases {
		if got := ExtractInts(c.in); !reflect.DeepEqual(got, c.want) {
			t.Errorf("ExtractInts(%q)=%v want %v", c.in, got, c.want)
		}
	}
}

