var nonAlnum = regexp.MustCompile(`[^a-z0-9]+`)

func Slugify(title string) string {
	s := strings.ToLower(title)
	s = nonAlnum.ReplaceAllString(s, "-") // runs of junk -> one hyphen
	return strings.Trim(s, "-")            // drop edge hyphens
}
